  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice clocks transformed precision timekeeping and furnish an exceptionally powerful platform for fundamental measurements.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye supplied decisive experimental development and realization.",
        "maturity": "Independent clocks now operate at extraordinary reproducible accuracy and support a broad measurement infrastructure.",
        "uncertainties": [
          "The relative division of conceptual and experimental credit across the wider clock community requires careful review."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions gave quantum computation a physically controllable, high-fidelity experimental foundation.",
        "attribution": "Cirac and Zoller established key architectures and protocols, while Blatt led landmark experimental demonstrations.",
        "maturity": "The platform has progressed from proof-of-principle operations to reproducible programmable processors.",
        "uncertainties": [
          "The candidate formulation overlaps broader atomic quantum-information work and its boundaries need precise definition."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made strong, engineered light-matter coupling available on a scalable solid-state platform.",
        "attribution": "Blais provided foundational theory, and Wallraff and Schoelkopf made the central experimental architecture convincing.",
        "maturity": "The effects are repeatedly measured and underpin a major quantum-circuit technology.",
        "uncertainties": [
          "Attribution among the several early superconducting-circuit groups is necessarily selective."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "John D. Teufel",
        "Markus Aspelmeyer"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion extends coherent quantum measurement into an intuitively macroscopic oscillator.",
        "attribution": "Cleland and Teufel made decisive circuit-based demonstrations, while Aspelmeyer established much of modern optomechanical control.",
        "maturity": "Ground-state preparation, coherent control, and quantum-limited readout have been demonstrated across complementary systems.",
        "uncertainties": [
          "The appropriate laureate set is difficult because Painter and Kippenberg also made foundational contributions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices became a uniquely clean and tunable laboratory for strongly correlated quantum matter.",
        "attribution": "Bloch and Greiner delivered defining experiments, with Zoller providing important theoretical vision for the field.",
        "maturity": "The Mott transition and subsequent lattice simulations are well replicated and have opened a durable research domain.",
        "uncertainties": [
          "Cirac and Zoller have broad overlapping claims in quantum simulation, and the candidate exceeds a three-person natural attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B029",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold molecules created a controlled setting for dipolar quantum matter, precision tests, and molecular quantum science.",
        "attribution": "DeMille, Doyle, and Ye each made central experimental advances toward controllable molecular ensembles.",
        "maturity": "The methods are established and now support reproducible many-body and precision-measurement experiments.",
        "uncertainties": [
          "The experimental lineage is broad and the decisive shared discovery is less sharply delimited than for lattice clocks."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Solid-state femtosecond lasers made compact ultrafast sources routine and enabled wide-ranging time-resolved science.",
        "attribution": "Moulton's gain-medium work, Keller's semiconductor-saturable-absorber concepts, and Sibbett's demonstrations are complementary.",
        "maturity": "The technology is long established, robust, and influential across spectroscopy and photonics.",
        "uncertainties": [
          "Credit for the broader ultrafast-laser revolution may be distributed among more contributors than this slate captures."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers created an unprecedented coherent ultrafast probe of atomic and molecular structure.",
        "attribution": "Pellegrini, Rossbach, and Kim represent key conceptual and accelerator-physics contributions to the field's realization.",
        "maturity": "Operational facilities and a large body of scientific applications demonstrate clear technical and scientific maturity.",
        "uncertainties": [
          "The achievement depended on major international facility teams, making individual attribution unusually challenging."
        ]
      }
    }
  ]
}
